 "content": "def transform(grid):
    """Extend colored diagonal segments that form a multi-color motif."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    qualifying = set()
    diagonals = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                if 0 <= r-dr < h and 0 <= c-dc < w:
                    continue
                line = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    line.append((rr, cc))
                    rr += dr
                    cc += dc
                diagonals.append(line)
                for i in range(len(line)-1):
                    y1,x1=line[i]; y2,x2=line[i+1]
                    color=grid[y1][x1]
                    if color != bg and grid[y2][x2] == color:
                        qualifying.add(color)
    # A lone diagonal motif is not extended (demo with color 4 remains unchanged).
    # Multiple aligned colors indicate the intended rays.
    if len(qualifying) < 2:
        return out
    for line in diagonals:
        for i in range(len(line)-1):
            y1,x1=line[i]; y2,x2=line[i+1]
            color=grid[y1][x1]
            if color == bg or color not in qualifying or grid[y2][x2] != color:
                continue
            j=i-1
            while j>=0:
                y,x=line[j]
                if grid[y][x] != bg: break
                out[y][x]=color
                j-=1
            j=i+2
            while j<len(line):
                y,x=line[j]
                if grid[y][x] != bg: break
                out[y][x]=color
                j+=1
    return out
